import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-05-10","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-05-10","date":"2023-05-10T00:00:00.000Z","updated":"2023-05-11T00:00:00.000Z","tags":["Ceph","Kafka","RGW","Code Review","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-10.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-10.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-10.md"};function o(n,a,s,h,u,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-kafka库在rgw中的应用与代码走查讨论" tabindex="-1">会议主题：Kafka库在RGW中的应用与代码走查讨论 <a class="header-anchor" href="#会议主题-kafka库在rgw中的应用与代码走查讨论" aria-label="Permalink to &quot;会议主题：Kafka库在RGW中的应用与代码走查讨论&quot;">​</a></h4><h4 id="与会人员-yuval-daniel-thomas-等" tabindex="-1">与会人员：Yuval, Daniel, Thomas 等 <a class="header-anchor" href="#与会人员-yuval-daniel-thomas-等" aria-label="Permalink to &quot;与会人员：Yuval, Daniel, Thomas 等&quot;">​</a></h4><h4 id="会议时间-2023年5月10日" tabindex="-1">会议时间：2023年5月10日 <a class="header-anchor" href="#会议时间-2023年5月10日" aria-label="Permalink to &quot;会议时间：2023年5月10日&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Kafka库实现问题讨论</strong></p><ul><li><strong>问题背景</strong>：用户在使用Kafka库时报告了回归问题，特别是在设置ACK级别时出现重试。</li><li><strong>问题分析</strong>：Yuval发现，问题源于Kafka库内部的重试机制与我们代码库中的机制冲突。我们的机制需要能够应对崩溃和重启等情况，而Kafka库的机制则无法持久化。</li><li><strong>解决方案讨论</strong>： <ul><li>讨论了禁用Kafka库内部重试机制的可行性。</li><li>提出允许用户通过配置文件控制Kafka库某些行为，以增加灵活性。</li><li>最终决定，在ACK级别为“broker”时允许内部重试，而在ACK级别为“none”时禁用。</li></ul></li></ul></li><li><p><strong>代码走查提议</strong></p><ul><li><strong>提议人</strong>：Daniel</li><li><strong>提议内容</strong>：提议进行代码走查，以传播关于RGW代码库的知识，特别是tracing和Lua代码的走查。</li><li><strong>反馈</strong>：Yuval表示对tracing的走查感兴趣，但希望在OSD编码问题解决后再进行。Thomas表示愿意进行Lua代码的走查。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>对于Kafka库的重试机制，决定在ACK级别为“broker”时允许内部重试，而在ACK级别为“none”时禁用。</li><li>允许用户通过配置文件控制Kafka库的某些行为，以增加灵活性。</li><li>计划进行代码走查，特别是关于tracing和Lua代码的走查。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Yuval将对Kafka库的重试机制进行调整，并提交相关Pull Request（PR）。</li><li>Daniel和Thomas将准备进行代码走查，具体时间待定。</li><li>需要关注OSD编码问题的解决进展，以便进行tracing的代码走查。</li></ul><h4 id="会议结束-感谢所有参与者的贡献-会议圆满结束。" tabindex="-1">会议结束：感谢所有参与者的贡献，会议圆满结束。 <a class="header-anchor" href="#会议结束-感谢所有参与者的贡献-会议圆满结束。" aria-label="Permalink to &quot;会议结束：感谢所有参与者的贡献，会议圆满结束。&quot;">​</a></h4>',11)])])}const _=e(r,[["render",o]]);export{g as __pageData,_ as default};
